components.css:
.ds-category{font-family:var(--font-sans,"Geist Variable",ui-sans-serif,system-ui,sans-serif);font-variant-numeric:tabular-nums;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px}.ds-category button{min-width:0;display:grid;align-content:center;justify-items:center;gap:4px;text-align:center;min-height:68px;padding:8px 5px;border:0;border-radius:6px;background:transparent;color:var(--color-dim,#a4b6bc);font:inherit;font-size:12px;line-height:1.3;text-wrap:balance;cursor:pointer}.ds-category button[aria-pressed="true"]{background:var(--color-raised,#1a2d35);color:var(--color-ink,#edf3f3)}.ds-category button:hover{color:var(--color-ink,#edf3f3)}.ds-explore:focus-visible,.ds-utility:focus-visible,.ds-tabs button:focus-visible,.ds-search input:focus-visible,.ds-projection button:focus-visible,.ds-category button:focus-visible,.ds-library:focus-visible,.ds-times-trigger:focus-visible,.ds-times-panel button:focus-visible{outline:2px solid var(--color-ink,#edf3f3);outline-offset:2px}
.ds-category svg{display:block;width:24px;height:20px;margin:0}@media(min-width:1280px){.ds-category{grid-template-columns:minmax(0,1fr) minmax(0,.85fr) minmax(0,1.45fr) minmax(0,.85fr)}.ds-category button{min-height:52px;padding:6px 3px}}
.ds-category span{max-width:100%}
